      { id: 'ca-sgn', airline: 'Air China', route: 'VIE–SGN', via: 'Beijing', stops: 1, durOut: 24, durBack: 26, arr: 'hcmc', dep: 'hcmc', pp: { low: 800, typ: 950, high: 1100 }, ev: 'est', bag: 'Bag usually included.', arrive: 'check the itinerary', note: 'Not among the flights Google showed for these dates, so this low price is only our guess from off-peak fares — do not count on it.', src: [src.ca] }
